local CollectionService = game:GetService("CollectionService")

function t.ApplySkin(p1) --[[ ApplySkin | Line: 9 | Upvalues: CollectionService (copy) ]]
	for k, v in pairs(p1:GetDescendants()) do
		if v:IsA("MeshPart") then
			v.TextureID = "rbxassetid://81072404342708"
		end

		if CollectionService:hasTag(v, "SkinPart") then
			CollectionService:RemoveTag(v, "SkinPart")
		end
	end

	p1:SetAttribute("AlternateColor", (ColorSequence.new({ ColorSequenceKeypoint.new(0, Color3.fromRGB(227, 212, 255)), ColorSequenceKeypoint.new(1, Color3.fromRGB(161, 130, 217)) })))
