	p1.HumanoidRootPart.ExtraLight.PointLight.Color = Color3.fromRGB(161, 130, 217)

	local Config = p1:WaitForChild("Config")

	Config:WaitForChild("HurtTexture").Texture = "rbxassetid://106022233381525"
